using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging.Abstractions;
using MKSANCrud.Data;
using MKSANCrud.Models;
using MKSANCrud.Services.Database;
using MKSANCrud.Services.Clinica;
using MKSANCrud.Services.Agendamento;
internal static class PsicologiaPostgresChecks {
 public static async Task RunAsync(Action<bool,string> check){var connection=Environment.GetEnvironmentVariable("CALLMED_TEST_DB")??throw new Exception("Isolated local database required");var cs=new Npgsql.NpgsqlConnectionStringBuilder(connection);if(cs.Host!="127.0.0.1"||!cs.Database!.StartsWith("callmed_test"))throw new Exception("Only isolated local test databases are accepted");MKSANContext Db()=>new(new DbContextOptionsBuilder<MKSANContext>().UseNpgsql(connection).Options);var clock=new ClinicaClock();
 await using(var db=Db()){await db.Database.EnsureDeletedAsync();await db.Database.EnsureCreatedAsync();db.Especialidades.Add(new(){Id=1,Nome="Psicologia clínica"});db.Medicos.Add(new(){Id=1,Nome="Profissional legado fictício",Crm="CRM-PRESERVADO",EspecialidadeId=1});db.Pacientes.AddRange(new Paciente{Id=1,Nome="Fictício A",Cpf="52998224725"},new Paciente{Id=2,Nome="Fictício B",Cpf="11144477735"});db.Consultas.Add(new(){Id=100,PacienteId=1,MedicoId=1,Data=clock.Hoje,Horario="10:00",DuracaoMinutos=30});await db.SaveChangesAsync();
 foreach(var table in new[]{"GuardasRegistrosPsicologicos","RegistrosPsicologicos","AutorizacoesResponsaveis"})await PgTestDdl.ExecuteAsync(db,"DROP TABLE IF EXISTS \"",table,"\" CASCADE");foreach(var col in new[]{"Crp","RegistroVerificadoEm","RegistroVerificadoPor","FonteVerificacaoRegistro","DuracaoPadraoMinutos","ResponsavelTecnico"})await PgTestDdl.ExecuteAsync(db,"ALTER TABLE \"Medicos\" DROP COLUMN \"",col,"\" CASCADE");await db.Database.ExecuteSqlRawAsync("ALTER TABLE \"Consultas\" DROP COLUMN \"DuracaoMinutos\"");db.ChangeTracker.Clear();await new DatabaseSchemaV32Initializer(db).AplicarAsync();await new DatabaseSchemaV32Initializer(db).AplicarAsync();var legacy=await db.Psicologos.SingleAsync();check(legacy.Crm=="CRM-PRESERVADO"&&legacy.Crp==null&&!legacy.HabilitadoClinicamente&&legacy.DuracaoPadraoMinutos==50,"V32 é aditiva, reaplicável e não converte CRM legado em CRP");check((await db.Consultas.SingleAsync()).DuracaoMinutos==30,"Migração preserva duração das consultas existentes");await db.Database.ExecuteSqlRawAsync("DROP TABLE IF EXISTS \"SaudeRotinas\", \"PedidosPrivacidade\"");await new DatabaseSchemaV33Initializer(db).AplicarAsync();await new DatabaseSchemaV33Initializer(db).AplicarAsync();
 var operacao=new OperacaoService(db,clock);await operacao.MarcarAsync("teste-pg",true,default);await operacao.MarcarAsync("teste-pg",false,default);var health=await db.SaudeRotinas.AsNoTracking().SingleAsync();check(health.SucessoEm!=null&&health.FalhaEm!=null&&health.FalhasConsecutivas==1,"V33 reaplicável registra saúde das rotinas no PostgreSQL sem perder sucesso anterior");
 var pedido=new PedidoPrivacidade{UsuarioId="titular-ficticio",Tipo="Acesso"};db.PedidosPrivacidade.Add(pedido);await db.SaveChangesAsync();await using(var concurrent=Db()){var stale=await concurrent.PedidosPrivacidade.SingleAsync(x=>x.Id==pedido.Id);pedido.Estado="Atendido";pedido.Versao=Guid.NewGuid();await db.SaveChangesAsync();stale.Estado="Parcial";stale.Versao=Guid.NewGuid();var blocked=false;try{await concurrent.SaveChangesAsync();}catch(DbUpdateConcurrencyException){blocked=true;}check(blocked,"Resposta concorrente não sobrescreve decisão de privacidade no PostgreSQL");}
 legacy.Crp="12/12345";legacy.RegistroVerificadoEm=DateTime.UtcNow;await db.SaveChangesAsync();
 db.RegistrosPsicologicos.Add(new(){Id=Guid.Parse("00000000-0000-0000-0000-000000000001"),ConsultaId=100,PacienteId=1,PsicologoId=1,AutorUsuarioId="fixture",Envelope="CIFRADO-FICTICIO",Hash="FICTICIO"});await db.SaveChangesAsync();var immutable=false;try{await db.Database.ExecuteSqlRawAsync("UPDATE \"RegistrosPsicologicos\" SET \"Envelope\"='ALTERADO'");}catch(Npgsql.PostgresException){immutable=true;}check(immutable,"Banco impede alteração direta de registro publicado");var restricted=false;try{await db.Database.ExecuteSqlRawAsync("DELETE FROM \"Consultas\" WHERE \"Id\"=100");}catch(Npgsql.PostgresException){restricted=true;}check(restricted,"Consulta com registro psicológico não é apagada por cascata");var day=clock.Hoje.AddDays(1);db.Disponibilidades.AddRange(new(){MedicoId=1,Data=day,Horario="10:00",Ativo=true},new(){MedicoId=1,Data=day,Horario="10:30",Ativo=true},new(){MedicoId=1,Data=day,Horario="10:50",Ativo=true});await db.SaveChangesAsync();}
 AgendamentoService Agenda(MKSANContext db){var conv=new ConvenioService(clock);return new(db,clock,new(db),conv,new(db,conv),NullLogger<AgendamentoService>.Instance);}async Task<ResultadoOperacaoConsulta> Book(int pid,string h){await using var db=Db();return await Agenda(db).AgendarAsync(pid,1,clock.Hoje.AddDays(1),h,null);}
 var race=await Task.WhenAll(Book(1,"10:00"),Book(2,"10:30"));check(race.Count(x=>x.Sucesso)==1,"Lock diário serializa disputa entre horários diferentes mas sobrepostos");await using(var db=Db()){var agenda=Agenda(db);var horas=await agenda.HorariosDisponiveisAsync(1,clock.Hoje.AddDays(1));var won=race.Single(x=>x.Sucesso).Consulta!;check(!horas.Contains(won.Horario=="10:00"?"10:30":"10:00"),"Horários oferecidos também excluem intervalos sobrepostos");}
 }
}
